import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        # dp[i] will store the maximum score starting from index i (0-based)
        # We compute from right to left
        dp = [0] * n

        max_score = 0

        for i in range(n - 1, -1, -1):
            val = a[i]
            next_idx = i + val

            if next_idx < n:
                dp[i] = val + dp[next_idx]
            else:
                dp[i] = val

            if dp[i] > max_score:
                max_score = dp[i]

        results.append(str(max_score))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
